/** 超大场景的文件生成器：返回与原样本逐项相同的 [路径, 内容] 列表。 */
export const GENERATED = {
  // 6005 份 md：固定 4 个文件在前，其后 app/m/<序号/100>/f<序号>.md（内容 "x\n"），序号 0..6004——超过 md 扫描上限（6000）
  'links-md-6000': () => [
    ['sys/.git/HEAD', 'ref: refs/heads/main\n'], ['app/.git/HEAD', 'ref: refs/heads/main\n'],
    ['sys/AGENTS.md', "# 系统仓\n\n本系统由这几个仓组成：sys（system）、app（active）。\n各仓状态见本文件。\n"], ['app/AGENTS.md', "# 应用仓 app\n\n本仓特有约束见下。系统级权威在 [系统仓](../sys/AGENTS.md)。\n"],
    ...Array.from({ length: 6005 }, (_, i) => [`app/m/${Math.floor(i / 100)}/f${i}.md`, 'x\n']),
  ],
  // 头部只读 64 KB：old/AGENTS.md 是 70000 个 x 加末尾「已退役」（标记在 64 KB 之后，看不见）；规则文件 a.md 是开头「已退役」加 70000 个 y（标记在头部，看得见）
  'retired-head-64k': () => [
    ['sys/.git/HEAD', 'ref: refs/heads/main\n'], ['old/.git/HEAD', 'ref: refs/heads/main\n'],
    ['sys/AGENTS.md', '# s\n\nsys（system）、old（retired）\n'],
    ['old/AGENTS.md', 'x'.repeat(70000) + '\n已退役\n'], ['old/.harness/rules/a.md', '已退役\n' + 'y'.repeat(70000) + '\n'],
  ],
}
